#include <iostream>
#include <queue>
#include <vector>

int shortestPath(const std::vector<std::vector<int>>& adj, int start, int end) {
    std::vector<int> dist(adj.size(), -1);
    dist[start] = 0;
    std::queue<int> queue;
    queue.push(start);
    while (!queue.empty()) {
        int node = queue.front();
        queue.pop();
        if (node == end) {
            return dist[node];
        }
        for (int neighbor : adj[node]) {
            if (dist[neighbor] == -1) {
                dist[neighbor] = dist[node] + 1;
                queue.push(neighbor);
            }
        }
    }
    return -1;
}

