const input = readFileSync(0, "utf8");

function shortestPath(adj: number[][], start: number, end: number): number {
  const dist: number[] = adj.map(() => -1);
  dist[start] = 0;
  const queue: number[] = [start];
  let head = 0;
  while (head < queue.length) {
    const node = queue[head++];
    if (node === undefined) {
      break;
    }
    const steps = dist[node] ?? 0;
    if (node === end) {
      return steps;
    }
    for (const neighbor of adj[node] ?? []) {
      if (dist[neighbor] === -1) {
        dist[neighbor] = steps + 1;
        queue.push(neighbor);
      }
    }
  }
  return -1;
}

